        c.fillStyle = col; c.beginPath(); c.moveTo(2, 24); c.quadraticCurveTo(0, 8, 10, 4); c.quadraticCurveTo(18, 0, 24, 8); c.quadraticCurveTo(29, 16, 26, 25); c.closePath(); c.fill();
        c.fillStyle = "rgba(255,255,255,0.22)"; c.beginPath(); c.ellipse(11, 9, 6, 3, -0.4, 0, Math.PI * 2); c.fill();
        c.fillStyle = "rgba(0,0,0,0.25)"; c.beginPath(); c.moveTo(4, 24); c.quadraticCurveTo(14, 28, 26, 24); c.lineTo(26, 20); c.quadraticCurveTo(14, 24, 4, 20); c.fill();
        c.strokeStyle = "rgba(0,0,0,0.5)"; c.lineWidth = 1.5; c.beginPath(); c.moveTo(2, 24); c.quadraticCurveTo(0, 8, 10, 4); c.quadraticCurveTo(18, 0, 24, 8); c.quadraticCurveTo(29, 16, 26, 25); c.stroke();
