          if (r1() < 0.006) { g.fillStyle(0x2a2c30, 1).fillCircle(x + 12, y + 12, 9); g.lineStyle(1.5, 0x5a5e64, 1).strokeCircle(x + 12, y + 12, 9).strokeCircle(x + 12, y + 12, 5); }
