      e.svx = snap ? vx : (e.svx || 0) + (vx - (e.svx || 0)) * Math.min(1, dt * 9);
      e.svy = snap ? vy : (e.svy || 0) + (vy - (e.svy || 0)) * Math.min(1, dt * 9);
      if (Math.abs(e.svx) > 1 || Math.abs(e.svy) > 1) this.move(e, e.svx * dt, e.svy * dt);
      if (Math.abs(e.svx) > 8) e.face = e.svx < 0 ? -1 : 1; else if (e.st === "aim" || e.st === "honk" || e.st === "wind") e.face = ux < 0 ? -1 : 1;
