        e.st = e.plan.pop(); e.sub = 0; e.ang = Math.random() * 6;
        e.t = { spiral: 2.6, burst: 1.8, shotgun: 1.6, leap: 1.1, summon: 1, charge: 1.6, rush: 1.6, spin: 2.8, bearcall: 1.4, rockslide: 2.2, teleport: 1.2, cards: 1.6, clones: 1, rattle: 1.6, cry: 1.8 }[e.st] || 1.5;
        if (e.st === "bearcall") { this.floatText(e.x, e.y - 90, "HWOOOOOO!", "#c8ff3a"); SFX.roar(); }
        if (e.st === "teleport") { e.hidden = true; this.burst("pink", 20, e.x, e.y - 30); SFX.wind(); }
        if (e.st === "cry") { this.floatText(e.x, e.y - 80, "WAAAAH!", "#ff8ad8"); }
        if (D.lines && Math.random() < 0.18) UI.voice(pick(D.lines));
        if (e.st === "leap") { e.l0 = { x: e.x, y: e.y }; e.l1 = { x: P.x, y: P.y }; SFX.wind(); }
        if (e.st === "charge") { e.cx = ux; e.cy = uy; e.windT = 0.55; SFX.wind(); }
        if (e.st === "spin") { const a = Math.atan2(uy, ux) + rnd(-0.4, 0.4); e.cx = Math.cos(a); e.cy = Math.sin(a); SFX.wind(); }
