    P.faceS = P.faceS === undefined ? P.face : P.faceS + (P.face - P.faceS) * Math.min(1, dt * 18);
    const flip = P.faceS < 0, turn = Math.max(0.25, Math.abs(P.faceS));
    const moving = Math.hypot(P.vx, P.vy) > 10 && P.rollT <= 0;
    // walk cycle: the legs swing from the hips, the body bobs twice per stride
    const spr = P.sprint || 0;
    P.amp = (P.amp || 0) + ((moving ? 1 : 0) - (P.amp || 0)) * Math.min(1, dt * 10);
    if (P.amp > 0.02) P.walk += dt * (8 + Math.hypot(P.vx, P.vy) / 26); else P.walk = 0;
    const sw = Math.sin(P.walk) * (0.42 + 0.32 * spr) * P.amp, bob = Math.abs(Math.cos(P.walk)) * (2 + 2 * spr) * P.amp + Math.sin(time * 0.004) * 0.5 * (1 - P.amp);
    P.bob = bob;
