    if (moving && foot !== P.foot) { P.foot = foot; if (spr > 0.3 || Math.random() < 0.3) this.burst("dust", spr > 0.5 ? 3 : 1, P.x - Math.sign(P.vx || 1) * 5, P.y); }
    // a fading copy trails behind at a full sprint
