    if (P.drop > 0) { P.drop -= dt || 0.016; const q = Math.max(0, P.drop / 0.45); lift = q * q * 120; if (P.drop <= 0) { this.burst("dust", 10, P.x, P.y); P.squash = 0.3; } }
    P.squash = Math.max(0, (P.squash || 0) - dt * 2.5);
    P.kick = Math.max(0, (P.kick || 0) - dt * 10);
    const sq = P.squash || 0, sx = 1 + sq * 0.6, sy = 1 - sq * 0.5;
    const hipY = P.y - (pk.h - pk.legTop) * S - lift;
